# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: sift
def sift(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: shape
def shape(xs, factor=10):
    return [v * factor for v in xs]

# region: render
def render(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: intake
def intake(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(emit(render(shape(sift(gather(raw))))))

